from collections import defaultdict

# Fill rules from demo:
# Border 3 (green) -> fill 7 (orange)
# Border 5 (blue) -> fill 7 (orange)  
# Border 6 (magenta) -> fill 2 (red)

fill_map = {3: 7, 5: 7, 6: 2}

# The pattern: fill hollow enclosures with color based on border
# Interior detection: find regions of one color (usually 9) completely surrounded by a border color

def has_borders_around(grid, center, border_color):
    """Check if all 4-connected neighbors have the border color"""
    h, w = len(grid), len(grid[0])
    r, c = center

    # Check all 4 neighbors
    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
        nr, nc = r + dr, c + dc
        if not (0 <= nr < h and 0 <= nc < w):
            return False  # Out of bounds means not surrounded
        if grid[nr][nc] != border_color:
            return False
    return True

def find_interiors(grid):
    """Find all cells that are in hollow enclosures"""
    h, w = len(grid), len(grid[0])
    interiors = set()

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 9:  # Check if it could be interior (background)
                border_found = False
                for neighbor_color in filled_map.keys():
                    if has_borders_around(grid, (r, c), neighbor_color):
                        interiors.add((r, c))
                        border_found = True
                        break
                # Also check diagonals for rectangular enclosures
                if border_found:
                    continue

    return interiors

# Let me directly check which cells should be filled
# A 9 cell is enclosed by border color X if all paths to grid boundary go through X

def is_enclosed(grid, r, c, border_color):
    """Check if cell (r,c) is enclosed by border_color"""
    h, w = len(grid), len(grid[0])

    if grid[r][c] != 9:
        return False

    # Try to reach boundary without crossing border_color
    visited = set()
    queue = deque([(r, c)])

    while queue:
        cr, cc = queue.popleft()
        if (cr, cc) in visited:
            continue
        visited.add((cr, cc))

        # Hit boundary
        if cr == 0 or cr == h-1 or cc == 0 or cc == w-1:
            return False  # Not enclosed

        # Skip border_color
        if grid[cr][cc] == border_color:
            continue

        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = cr + dr, cc + dc
            if 0 <= nr < h and 0 <= nc < w:
                if (nr, nc) not in visited:
                    queue.append((nr, nc))

    # If we exhausted the queue without hitting boundary, it's enclosed
    return True

def find_all_enclosed_cells(grid):
    """Find all 9 cells that are enclosed"""
    enclosed = {}  # border_color -> list of (r,c) that should be filled

    for border_color in fill_map.keys():
        enclosed[border_color] = []
        for r in range(len(grid)):
            for c in range(len(grid[0])):
                if is_enclosed(grid, r, c, border_color):
                    enclosed[border_color].append((r, c))
    return enclosed

