def apply_fill(grid, fill_map):
    """Fill all 9 regions that are bounded by a border"""
    h, w = len(grid), len(grid[0])
    result = [[grid[r][c] for c in range(w)] for r in range(h)]

    # Flood fill to find connected regions of 9s
    visited = [[False]*w for _ in range(h)]
    directions = [(-1,0), (1,0), (0,-1), (0,1)]

