                    visited[r][c] = True
                    region.append((r, c))

                    for dr, dc in directions:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < h and 0 <= nc < w:
                            if grid[nr][nc] == 9 and not visited[nr][nc]:
                                stack.append((nr, nc))

                # Check if any border color completely surrounds this region
                # A region is surrounded by border_color if all 4-connect neighbors
                # are either border_color or out of bounds
                for color, fill in fill_map.items():
                    # Check if region is bounded by this color
